export function searchLibrary(query: string): LibraryExercise[] {
  const words = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  if (words.length === 0) return [];

  const matches = EXERCISE_LIBRARY.filter((ex) => {
    const name = ex.name.toLowerCase();
    return words.every((w) => name.includes(w));
  });

  const fullQuery = query.trim().toLowerCase();
  matches.sort((a, b) => {
    const aName = a.name.toLowerCase();
    const bName = b.name.toLowerCase();
    // Prefer names that start with the full query, then names containing the
    // full query as a contiguous phrase, then everything else alphabetically.
    const aStarts = aName.startsWith(fullQuery) ? 0 : aName.includes(fullQuery) ? 1 : 2;
    const bStarts = bName.startsWith(fullQuery) ? 0 : bName.includes(fullQuery) ? 1 : 2;
    if (aStarts !== bStarts) return aStarts - bStarts;
    return aName.localeCompare(bName);
  });

  return matches.slice(0, 30);
}
const nameToImage = new Map(EXERCISE_LIBRARY.map((ex) => [ex.name.toLowerCase(), ex.image]));

export function getExerciseImage(name: string): string | undefined {
  return nameToImage.get(name.trim().toLowerCase());
}
